KIND='target-part-diagnostic-opposite-lower-limb-mirror'
OP='frozen-opposite-frame-reflection'
PAIRS={'shinl':('shinr','troll-left-leg-axis-radial-diagnostic'),'legl':('legr','target-part-diagnostic-thigh-proximal-backward-Y')}
PENDING=('geometryAccepted','anatomyAccepted','connectorAccepted','materialAccepted','nativeAccepted','stagingAccepted','clientAccepted','productionAccepted','selectionMade')
ORDER=np.array([0,2,1])

def validate_config(c,tp,target):
    tc.require(c.get('schemaVersion')==1 and c.get('kind')=='troll-opposite-lower-limb-diagnostic-mirror-config' and c.get('coordinateSpace')=='working' and c.get('diagnosticOnly') is True,'Explicit working diagnostic mirror config required')
    tc.require(target['identity'].get('race')=='troll' and target['identity']['gender']=='male' and target['identity']['prefix']=='pmg0','Troll male only; no Human/default reinterpretation')
    src=c['sourcePart'];tc.require(src in PAIRS and (c['part'],c['sourceKind'])==PAIRS[src],'Only exact LEFT85shin or LEFTback20thigh opposite pair/type')
    part=c['part'];tc.require(c['sourceJoint']==tc.PART_JOINTS[src] and c['joint']==tc.PART_JOINTS[part] and c['model']==tc.model(target,part),'Declared resource ownership')
    tc.require(str(Path(c['targetContract']).resolve())==str(Path(tp).resolve()) and c['targetContractSha256']==tc.sha(tp) and c['rigRevision']==target['rig']['revision'],'Exact frozen target')
    tc.require(c['statureApplications']==0 and c['factor85Reapplied'] is False and c['proximalBackFieldReapplied'] is False and c['sourceCornerPermutation']==[0,2,1] and c['tangentWReflectionFactor']==-1,'Single reflection only; no fit/85/back20/runtime repeat')
    tc.require(c['planeOriginWorld']==[0.,0.,0.] and c['planeNormalWorld']==[1.,0.,0.],'Exact existing X0 world reflection plane')
    H=tc.frame(target,c['sourceJoint'],'working');G=tc.frame(target,c['joint'],'working');M,R=reflection_between_frames(H,G,c['planeOriginWorld'],c['planeNormalWorld']);tc.require(np.array_equal(c['sourceAttachmentWorld'],H) and np.array_equal(c['attachmentWorld'],G) and np.array_equal(c['sourceToAttachmentLocal'],M) and np.array_equal(c['reflectionWorld'],R),'Frozen opposite-frame conjugation differs');return H,G,M,R

def validate_approval(a,c):
    tc.require(a.get('kind')=='root-approved-opposite-lower-limb-diagnostic-mirror' and a.get('reviewedBy')=='/root' and a.get('authorizeImplementationAndOneFreshExport') is True and a.get('configuration')==c,'Exact executed root mirror approval required')

def load_parent(c,tp,target,pins):
    rp=input_pin(c['sourceReceipt']['path'],c['sourceReceipt']['sha256'],pins,c);r=json.loads(rp.read_text());tc.verify_binding(r,tp,target,'working');source=input_pin(c['sourceCandidate']['path'],c['sourceCandidate']['sha256'],pins,c);tc.require(r['kind']==c['sourceKind'] and r['part']==c['sourcePart'] and r['joint']==c['sourceJoint'] and r['candidate']==str(source) and r['candidateSha256']==c['sourceCandidate']['sha256'] and r['statureApplications']==0,'Exact selected diagnostic parent association')
    for p,h in r['frozenInputs'].items():input_pin(p,h,pins,c)
    ap=input_pin(c['sourceNativeCornerArchive']['path'],c['sourceNativeCornerArchive']['sha256'],pins,c);tc.require(c['sourceNativeCornerArchive']==r['nativeCornerArchive'],'Original authoritative native archive association')
    with np.load(ap,allow_pickle=False) as a:arc={k:a[k].copy() for k in a.files}
    doc,blob=read_glb(source);tc.require(doc['nodes']==[{'name':'detached_geometry','mesh':0}] and len(doc['meshes'])==1 and len(doc['meshes'][0]['primitives'])==1,'One identity detached primitive');prim=doc['meshes'][0]['primitives'][0];F=accessor(doc,blob,prim['indices']).reshape(-1,3).astype(np.int64);rows={s:accessor(doc,blob,prim['attributes'][s]) for s in ['POSITION','NORMAL','TANGENT','TEXCOORD_0']}
    if c['sourcePart']=='legl':
        verified=verify_back20(rp,tp,target);pins.update(verified['inputs'])
    else:
        tc.require(r['schemaVersion']==1 and r['factor']==.85 and r['diagnosticOnly'] is True and r['selectionMade'] is False and all(r[k] is False for k in ['anatomyAccepted','connectorAccepted','materialAccepted','clientAccepted','productionAccepted']),'Unpromoted exact shin85 parent')
        fp=input_pin(r['parentGeometryReceipt'],r['parentGeometryReceiptSha256'],pins,c);orig=input_pin(r['parentCandidate'],r['parentCandidateSha256'],pins,c);fit=verify_source_receipt(orig,fp,tp,target,'shinl','working');tc.require(fit['operation']=='fit' and fit['reflectionWorld'] is None,'Proper uniform original shin fit required');H=tc.frame(target,'lshin_g','working');K=tc.frame(target,'lfoot_g','working');M,d,L=radial_matrix(H[:3,3],K[:3,3],.85);ML=np.linalg.inv(H)@M@H;tc.require(np.array_equal(H,r['attachmentWorld']) and np.array_equal(M,r['worldAffine']) and np.array_equal(ML,r['localAffine']) and np.array_equal(d,r['axisUnitWorld']) and L==r['jointSpanMetres'],'Actual shin85 axis/field ancestry')
        od,ob=read_glb(orig);op=od['meshes'][0]['primitives'][0];old={s:accessor(od,ob,op['attributes'][s]) for s in ['POSITION','NORMAL','TANGENT']};active=np.zeros(len(old['POSITION']),bool);active[np.unique(F)]=True;expected={s:v.copy() for s,v in old.items()};expected['POSITION'][active]=(transform_positions(old['POSITION'][active].astype(float)@BASIS.T,ML)@BASIS).astype('<f4');n=old['NORMAL'][active].astype(float)@BASIS.T;t=old['TANGENT'][active].astype(float);t[:,:3]=t[:,:3]@BASIS.T;en,et=transport(n,t,ML[:3,:3]);expected['NORMAL'][active]=(en@BASIS).astype('<f4');et[:,:3]=et[:,:3]@BASIS;expected['TANGENT'][active]=et.astype('<f4');ed,eb=append_attributes(od,ob,expected);tc.require(ed==doc and eb==blob,'Exact shin85 serialized arrays/BIN/metadata provenance')
        originalArchive=input_pin(fit['nativeCornerArchive']['path'],fit['nativeCornerArchive']['sha256'],pins,c)
        with np.load(originalArchive,allow_pickle=False) as a:base={k:a[k].copy() for k in a.files}
        for k in set(base)-{'positions','normals','tangents'}:tc.require(base[k].dtype==arc[k].dtype and base[k].tobytes()==arc[k].tobytes(),'Source f64 corner provenance '+k)
        ep=transform_positions(base['positions'].reshape(-1,3),ML).reshape(base['positions'].shape);en,et=transport(base['normals'].reshape(-1,3),base['tangents'].reshape(-1,4),ML[:3,:3]);tc.require(ep.tobytes()==arc['positions'].tobytes() and en.reshape(base['normals'].shape).tobytes()==arc['normals'].tobytes() and et.reshape(base['tangents'].shape).tobytes()==arc['tangents'].tobytes(),'Authoritative shin85 f64 PNT exact')
    tc.require(np.array_equal(arc['sourceTriangleIds'],np.arange(len(F))) and np.array_equal(arc['sourceCornerOrder'],np.tile([0,1,2],(len(F),1))) and np.array_equal(arc['primitiveIds'],np.zeros(len(F),int)),'Original face/corner ownership required');tc.require(np.array_equal(arc['uvGltf'],rows['TEXCOORD_0'][F]),'Literal source UV association');return r,doc,blob,rows,F,arc

def mirror_archive(arc,M):
    result={};result['positions']=(arc['positions']@M[:3,:3].T+M[:3,3])[:,ORDER];result['normals']=(arc['normals']@M[:3,:3].T)[:,ORDER];t=arc['tangents'].copy();t[...,:3]=t[...,:3]@M[:3,:3].T;t[...,3]*=-1;result['tangents']=t[:,ORDER]
    for k in ['uvNative','uvGltf','sourceCornerOrder']:result[k]=arc[k][:,ORDER].copy()
    for k in ['sourceTriangleIds','primitiveIds','tangentTriangleIds']:
        if k in arc:result[k]=arc[k].copy()
    result['mirrorParentCornerOrder']=np.tile(ORDER,(len(arc['positions']),1));result['mirrorParentSourceCornerOrder']=arc['sourceCornerOrder'].copy()
    for k in ['positions','normals','tangents','uvNative','uvGltf']:result['mirrorParent'+k[0].upper()+k[1:]]=arc[k].copy()
    return result

def proof(old,blob,new,nb,rows,F,native,H,G,M,R):
    p=new['meshes'][0]['primitives'][0];nr={s:accessor(new,nb,p['attributes'][s]) for s in rows};nf=accessor(new,nb,p['indices']).reshape(-1,3).astype(np.int64);tc.require(np.array_equal(nf,F[:,ORDER]) and nb[:len(blob)]==blob and embedded_maps(old,blob)==embedded_maps(new,nb),'Exact winding/BIN/maps');tc.require(new['accessors'][:len(old['accessors'])]==old['accessors'] and new['bufferViews'][:len(old['bufferViews'])]==old['bufferViews'] and new['materials']==old['materials'],'Original accessor/material definitions')
    for s,aid in old['meshes'][0]['primitives'][0]['attributes'].items():tc.require(accessor(old,blob,aid,allow_normalized=True).tobytes()==accessor(new,nb,aid,allow_normalized=True).tobytes(),'Stored original '+s)
    world=rows['POSITION'].astype(float)@BASIS.T@H[:3,:3].T+H[:3,3];nw=nr['POSITION'].astype(float)@BASIS.T@G[:3,:3].T+G[:3,3];err=float(np.max(abs(nw-(world@R[:3,:3].T+R[:3,3]))));tc.require(err<4e-8,'Frozen frame world reflection placement');tc.require(nr['TEXCOORD_0'].tobytes()==rows['TEXCOORD_0'].tobytes() and np.array_equal(native['uvGltf'],nr['TEXCOORD_0'][nf]),'UV literal; no V/U repeat');tc.require(nr['TANGENT'][:,3].tobytes()==(-rows['TANGENT'][:,3]).tobytes(),'Tangent W exact reflection')
    P=rows['POSITION'];Q=nr['POSITION'];before=topology(P,F);after=topology(Q,nf)
    for k in TOPOLOGY_KEYS:tc.require(before[k]==after[k],'Introduced mirrored topology '+k)
    _,a=np.unique(P,axis=0,return_inverse=True);_,b=np.unique(Q,axis=0,return_inverse=True);tc.require(len(np.unique(np.column_stack([a,b]),axis=0))==len(np.unique(a))==len(np.unique(b)),'Coordinate weld partition changed')
    oldlocal=P.astype(float)@BASIS.T;newlocal=Q.astype(float)@BASIS.T;gn=np.cross(newlocal[nf[:,1]]-newlocal[nf[:,0]],newlocal[nf[:,2]]-newlocal[nf[:,0]]);on=np.cross(oldlocal[F[:,1]]-oldlocal[F[:,0]],oldlocal[F[:,2]]-oldlocal[F[:,0]]);expected=on@M[:3,:3].T;areas=np.linalg.norm(gn,axis=1);tc.require((areas>2e-15).all(),'Mirrored zero area');dots=np.sum(expected*gn,axis=1)/np.linalg.norm(expected,axis=1)/areas;tc.require(dots.min()>0,'Serialized reflected/winding-corrected orientation reversal')
    errors={'positions':float(np.max(abs(native['positions']-newlocal[nf]))),'normals':float(np.max(abs(native['normals']-nr['NORMAL'].astype(float)[nf]@BASIS.T)))};tt=nr['TANGENT'].astype(float).copy();tt[:,:3]=tt[:,:3]@BASIS.T;errors['tangents']=float(np.max(abs(native['tangents']-tt[nf])));tc.require(errors['positions']<1e-7 and errors['normals']<2e-6 and errors['tangents']<2e-6,'Decoded authoritative f64 corner bridge');return {'beforeTopology':{k:before[k] for k in TOPOLOGY_KEYS},'afterTopology':{k:after[k] for k in TOPOLOGY_KEYS},'originalStoredArraysBINUVMaterialsMapsExact':True,'coordinateWeldPartitionBijection':True,'minimumWindingCorrectedGeometricNormalDot':float(dots.min()),'worldReflectionSerializationMaxErrorMetres':err,'authoritativeCornerBridgeMaxErrors':errors,'sourceIntersectionAndOpenSurfaceRisksInherited':True,'noExhaustiveAllPoseClientClaim':True}

def execute(approval_path,output):
    ap=Path(approval_path).resolve();a=json.loads(ap.read_text());c=a['configuration'];validate_approval(a,c);pins={};input_pin(ap,tc.sha(ap),pins,c);cp=input_pin(a['proposal']['path'],a['proposal']['sha256'],pins,c);tc.require(json.loads(cp.read_text())==c,'Exact proposed config association');tp=input_pin(c['targetContract'],c['targetContractSha256'],pins,c);target=tc.load(tp);H,G,M,R=validate_config(c,tp,target);r,doc,blob,rows,F,arc=load_parent(c,tp,target,pins);nd,nb,discardFloat32DerivedArchive,bake=detached_affine_bake(doc,blob,M,True);native=mirror_archive(arc,M);pr=proof(doc,blob,nd,nb,rows,F,native,H,G,M,R);output=Path(output).resolve();tc.require(not output.exists(),'Fresh immutable mirror child required');helpers=[Path(__file__),Path(__file__).with_name('test_diagnostic_opposite_lower_limb.py')]+[Path(__file__).with_name(n) for n in ['diagnostic_axis_radial.py','diagnostic_thigh_proximal_back.py','diagnostic_connector_shear.py','mirror_stock_limb_part.py','target_contract.py','target_part_pipeline.py','place_purposebuilt_pelvis.py','conservative_face_selection.py']]
    if 'sourceBoundPlan' in a:input_pin(a['sourceBoundPlan']['path'],a['sourceBoundPlan']['sha256'],pins,c)
    for p in helpers:input_pin(p,tc.sha(p),pins,c)
    output.mkdir(parents=True);candidate=output/'candidate-local.glb';write_glb(candidate,nd,nb);archive=output/'native-float64-mirrored-corners.npz';np.savez_compressed(archive,**native);(output/'helpers').mkdir();snaps={}
    for p in helpers:dest=output/'helpers'/p.name;shutil.copyfile(p,dest);snaps[str(p.resolve())]={'path':str(dest),'sha256':tc.sha(dest)}
    result={'schemaVersion':1,'kind':KIND,'operation':OP,**tc.binding(tp,target,'working'),'part':c['part'],'joint':c['joint'],'model':c['model'],'sourcePart':c['sourcePart'],'sourceKind':c['sourceKind'],'diagnosticOnly':True,'canonicalNativeLineage':False,'candidate':str(candidate),'candidateSha256':tc.sha(candidate),'candidateToAttachmentLocal':np.eye(4).tolist(),'attachmentWorld':G.tolist(),'sourceAttachmentWorld':H.tolist(),'sourceToAttachmentLocal':M.tolist(),'reflectionWorld':R.tolist(),'sourceReceipt':c['sourceReceipt'],'sourceCandidate':c['sourceCandidate'],'parentNativeCornerArchive':c['sourceNativeCornerArchive'],'nativeCornerArchive':{'path':str(archive),'sha256':tc.sha(archive)},'rootApproval':{'path':str(ap),'sha256':tc.sha(ap)},'fieldConfiguration':c,'originalParentArchiveRetainedUnchanged':True,'nativeCornersDerivedFromAuthoritativeFloat64NotBakeArchive':True,'sourceCornerPermutation':[0,2,1],'statureApplications':0,'factor85Reapplied':False,'proximalBackFieldReapplied':False,'rigOrNeighborsChanged':False,'bakeProof':bake,'proof':pr,'frozenInputs':pins,'helperSnapshots':snaps,'limits':['Same diagnostic status and original open/internal/anatomy/material risks as selected LEFT parent.','Frozen opposite-frame stock asymmetries are retained, not corrected by joint movement.','No native/staging/client/production acceptance; canonical and Human receipt guards unchanged.'],**{k:False for k in PENDING}};rp=output/'diagnostic-opposite-geometry.json';rp.write_text(json.dumps(result,indent=2)+'\n');verify_receipt(rp,tp,target);return rp

def verify_receipt(receipt_path,target_path,target,space='working'):
    path=Path(receipt_path).resolve();r=json.loads(path.read_text());tc.require(r['schemaVersion']==1 and r['kind']==KIND and r['operation']==OP and space=='working' and r['diagnosticOnly'] is True and r['canonicalNativeLineage'] is False and all(r[k] is False for k in PENDING),'Exact unpromoted typed opposite working diagnostic');tc.verify_binding(r,target_path,target,space);c=r['fieldConfiguration'];H,G,M,R=validate_config(c,target_path,target);tc.require(r['part']==c['part'] and r['joint']==c['joint'] and r['model']==c['model'] and r['sourcePart']==c['sourcePart'] and r['sourceKind']==c['sourceKind'] and np.array_equal(r['attachmentWorld'],G) and np.array_equal(r['candidateToAttachmentLocal'],np.eye(4)) and r['statureApplications']==0 and r['factor85Reapplied'] is False and r['proximalBackFieldReapplied'] is False,'Exact target/source frame identity; no scale repeat');pins={}
    for p,h in r['frozenInputs'].items():input_pin(p,h,pins,c)
    a=json.loads(Path(r['rootApproval']['path']).read_text());validate_approval(a,c);parent,doc,blob,rows,F,arc=load_parent(c,target_path,target,pins);tc.require(tc.sha(r['candidate'])==r['candidateSha256'] and tc.sha(r['nativeCornerArchive']['path'])==r['nativeCornerArchive']['sha256'],'Child and archive pins');nd,nb=read_glb(r['candidate']);ed,eb,unused,bake=detached_affine_bake(doc,blob,M,True);tc.require(nd==ed and nb==eb,'Exact reflection arrays/metadata/BIN');native=mirror_archive(arc,M)
    with np.load(r['nativeCornerArchive']['path'],allow_pickle=False) as z:tc.require(set(z.files)==set(native) and all(z[k].dtype==v.dtype and z[k].shape==v.shape and z[k].tobytes()==v.tobytes() for k,v in native.items()),'Exact authoritative f64 mirrored arrays and literal parent correspondence')
    pr=proof(doc,blob,nd,nb,rows,F,native,H,G,M,R);tc.require(pr==r['proof'],'Mirrored proof differs');pins.update({str(path):tc.sha(path),r['candidate']:r['candidateSha256'],r['nativeCornerArchive']['path']:r['nativeCornerArchive']['sha256']});return {'receipt':r,'candidate':Path(r['candidate']),'inputs':pins,'primitiveInventory':[{'primitive':0,'part':r['part'],'material':nd['meshes'][0]['primitives'][0]['material'],'faces':len(F),'sourcePart':r['sourcePart']}]}
if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--approval',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();r=execute(a.approval,a.output);print(json.dumps({'receipt':str(r),'sha256':tc.sha(r)}),flush=True)
